<?php require_once __DIR__.'/../config/config.php';$u=role_required(['production']);$pageTitle='Accepted Articles';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];if(in_array($status,['PRODUCTION','PROOF_SENT','PROOF_APPROVED','PUBLISHED'],true)){$s=$pdo->prepare('UPDATE manuscripts SET status=?,published_at=? WHERE id=?');$s->execute([$status,$status==='PUBLISHED'?date('Y-m-d H:i:s'):null,$id]);$s=$pdo->prepare('INSERT INTO production(manuscript_id) VALUES(?) ON DUPLICATE KEY UPDATE manuscript_id=VALUES(manuscript_id)');$s->execute([$id]);audit('PRODUCTION_STATUS',$id,$status);}}$rows=$pdo->query("SELECT * FROM manuscripts WHERE status IN ('ACCEPTED','PRODUCTION','PROOF_SENT','PROOF_APPROVED') ORDER BY accepted_at DESC")->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">Accepted Articles & Production</h1><div class="panel"><table><tr><th>ID</th><th>Title</th><th>Status</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['manuscript_no'])?></td><td><?=e($r['title'])?></td><td><?=e(slabel($r['status']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>PRODUCTION</option><option>PROOF_SENT</option><option>PROOF_APPROVED</option><option>PUBLISHED</option></select><button class="btn primary">Update</button></form></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>